import{_ as t,o as a,c as r,ak as s}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"UI overview","description":"A map of the dashboard: every page and tab, what it is for, and the page of these docs that explains it.","frontmatter":{"title":"UI overview","description":"A map of the dashboard: every page and tab, what it is for, and the page of these docs that explains it.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/ui-overview.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/ui-overview.html"}],["meta",{"property":"og:title","content":"UI overview | Piwi Dashboard"}],["meta",{"property":"og:description","content":"A map of the dashboard: every page and tab, what it is for, and the page of these docs that explains it."}]]},"headers":[],"relativePath":"features/ui-overview.md","filePath":"features/ui-overview.md","lastUpdated":1791285777000}'),o={name:"features/ui-overview.md"};function n(i,e,h,l,c,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="ui-overview" tabindex="-1">UI overview <a class="header-anchor" href="#ui-overview" aria-label="Permalink to &quot;UI overview&quot;">​</a></h1><p>This page is a <strong>map of the dashboard</strong>: where each view lives and which page of these docs explains it.</p><p>Pages refresh on their own when runs start or finish. Blocks that need it carry a help icon with a short explanation and a <strong>Learn more</strong> link into these docs, and every source path <a href="./ide-integration.html">opens in your IDE</a>.</p><h2 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h2><p><code>/</code>: a health check across all projects. A <strong>stat strip</strong> whose every number but the average pass rate is a link, the <strong>failure inbox</strong> of open clusters, triaged from the row or the keyboard (<a href="./failure-clusters.html#the-failure-inbox">Failure clusters &amp; the inbox</a>), a <strong>Project health</strong> table with run-history bars and a tendency badge, and recent activity.</p><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><p><code>/analytics</code>: trends across projects and over time, where Home shows what is happening now. The filters at the top scope every widget; the widgets are listed on <a href="/reference/analytics-widgets.html">Analytics widgets</a>, and the filters and period comparisons on <a href="./analytics.html">Analytics</a>. The page is the built-in <em>Overview</em> <a href="./dashboards.html">dashboard</a>, and the header switcher opens the others. <a href="./timeline-markers.html">Timeline markers</a> overlay deploys and infrastructure changes on the trend charts.</p><h2 id="quality-reports" tabindex="-1">Quality reports <a class="header-anchor" href="#quality-reports" aria-label="Permalink to &quot;Quality reports&quot;">​</a></h2><p><code>/reports</code>: the report snapshots kept and the schedules that send them; <code>/reports/:id</code> opens one snapshot. See <a href="./quality-reports.html">Quality reports</a>.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p><code>/projects</code>: every project with search, tag filters, its last run and pass/fail bar. A project is created on its first result, or with <strong>New project</strong>.</p><h2 id="project-detail" tabindex="-1">Project detail <a class="header-anchor" href="#project-detail" aria-label="Permalink to &quot;Project detail&quot;">​</a></h2><p><code>/projects/:id</code>: one project&#39;s history. A <strong>status line</strong> gives the latest run, the pass rate over the last 20 runs and the open clusters, flaky and quarantined counts, and one <strong>filter bar</strong> (environment, branch, full runs only) scopes every list. The <strong>More</strong> menu holds Edit, <a href="./test-functions.html">Test functions</a>, <a href="./test-selection.html">Selections</a>, <a href="/guide/importing-runs.html">Import</a> and Delete. The tabs:</p><ul><li><strong>Runs</strong>: the run trend chart, with its <a href="./timeline-markers.html">timeline markers</a>, over every run, and the runs table, 50 runs to a page; select two runs and <strong>Compare</strong> to see <a href="./run-changes.html">what changed</a> between them, or select any number, page by page (the header box selects the page&#39;s runs), and <a href="/operate/storage.html#storage-management">delete them</a>.</li><li><strong>Tests</strong>: every test case with its pass rate and last run, in file order, with the <a href="/reference/test-search.html">test search</a> (title, describe block, file, tag, lock, owner, priority, feature) and a status filter, and groupable by file, or by file and describe block.</li><li><strong>Failures</strong>: the <a href="./failure-clusters.html">failure clusters</a>, the <a href="./flaky-tests.html#flaky-test-detection">flaky tests</a> and the <a href="./flaky-tests.html#quarantine-with-a-way-out">quarantine</a> list.</li><li><strong>Flake Lab</strong>: where each flaky test stands in the <a href="./flake-lab.html">Flake Lab</a> and the command it needs next, and the project&#39;s newest experiments. Hidden when the Flake Lab is switched off.</li><li><strong>Gaps</strong>: the tests the suite does not have yet, proposed from the Test Map, with the feature map and the graph view (<a href="./scenario-gaps.html">Scenario gaps &amp; the Test Map</a>). Hidden when the Test Map is switched off.</li><li><strong>Performance</strong>: duration trends, the slowest tests, timeout opportunities and the slow endpoints (<a href="./slow-tests.html">Slow tests &amp; wasted time</a>).</li><li><strong>Settings</strong>: one section at a time, picked from a menu beside it: the label and tags, the project&#39;s <a href="/operate/project-access.html">members</a>, <a href="/guide/source-control.html">source control</a> (token, default branch, CI re-run), <a href="./ai-diagnosis.html#custom-instructions">AI instructions</a>, <a href="/operate/capabilities.html">capabilities</a>, <a href="./analytics.html#targets">targets</a>, the <a href="./issue-tracking.html">issue tracker</a>, the <a href="./extension-connection.html#url-patterns">browser extension URLs</a> and, in the desktop app, the <a href="./desktop.html#running-tests-from-the-app">local folder</a>.</li></ul><h2 id="locators" tabindex="-1">Locators <a class="header-anchor" href="#locators" aria-label="Permalink to &quot;Locators&quot;">​</a></h2><p><code>/projects/:id/locators</code>: check pasted locators against the ones the project&#39;s tests use, and browse every locator chain in the locator index, per branch. See <a href="./locator-usage.html#the-locators-page">Who uses a locator</a>.</p><h2 id="test-run-detail" tabindex="-1">Test run detail <a class="header-anchor" href="#test-run-detail" aria-label="Permalink to &quot;Test run detail&quot;">​</a></h2><p><code>/test-runs/:id</code>: one run. The header carries the status, the primary action (<strong>Copy retry command</strong> on a red run, the HTML report on a green one) and one facts line, and a <strong>count bar</strong> filters the tests by status. While it runs, results stream in live. When ingest left something out or rebuilt it, the facts line counts <strong>ingest notes</strong> and <strong>Details</strong> lists them: steps and console entries over the <a href="/reference/configuration.html#ingest-limits">ingest caps</a>, traces not stored, evidence rebuilt from a trace, and the fallback the reporter took to send the run. The tabs:</p><ul><li><strong>Tests</strong>: every execution with its failure headline, in run order, grouped by cluster (the default on a red run), file, describe block or <a href="/reference/test-metadata.html#test-locks">lock</a>, with the same <a href="/reference/test-search.html">test search</a> as a project&#39;s Tests tab and bulk triage.</li><li><strong>Changes</strong>: what differs against one baseline run. See <a href="./run-changes.html">What changed in a run</a>.</li><li><strong>Timeline</strong>: each worker&#39;s tests on one time axis, with hooks, waits and locks, the slowest tests and the worker distribution (<a href="./slow-tests.html">Slow tests &amp; wasted time</a>). <ul><li><strong>Hooks</strong>: hook time is hatched over each test&#39;s bar: setup (<code>beforeAll</code>, <code>beforeEach</code>, fixtures) at the start, teardown (<code>afterEach</code>, <code>afterAll</code>, worker cleanup) at the end. A failed hook is drawn in dark red and counted in the header, even with <strong>Show hooks</strong> off; hover it for the hooks that section ran, their times and the error, and click it to open the test&#39;s steps on that hook. Playwright leaves <code>beforeAll</code> / <code>afterAll</code> hooks and worker fixtures out of a test&#39;s duration; the bar spans them anyway, and its tooltip gives the duration Playwright reported. Runs sent by an older reporter show the sections without their hook list.</li><li><strong>Gaps</strong>: a lane is one worker. Playwright replaces a worker process after a failed test (and starts one for tests that need another project or different worker options), so a lane can hold several processes one after another: <strong>↻</strong> marks where a new one took over, and the stretch before it is the old process shutting down and the new one starting. A dashed line is time the worker ran no test — before its first test, between two tests, or after its last one while the others finished. Hover either to see which it was.</li><li><strong>Resources</strong>: when the reporter measured them, the machine&#39;s CPU, the run&#39;s memory and the pages open in the workers are drawn above the worker rows, on the same axis, and one metric of your choice under each worker row. Hover a track for its values at that moment; turn each one off from the <strong>Resources</strong> menu. See <a href="./cpu-memory-disk.html#in-the-dashboard">CPU, memory &amp; disk</a>.</li></ul></li></ul><h2 id="test-case-detail" tabindex="-1">Test case detail <a class="header-anchor" href="#test-case-detail" aria-label="Permalink to &quot;Test case detail&quot;">​</a></h2><p>Two pages: an <strong>execution</strong> (<code>/test-run-cases/:id</code>) answers <em>&quot;why did this attempt fail?&quot;</em>, and a <strong>test case</strong> (<code>/test-cases/:id</code>) answers <em>&quot;how has this test behaved over time?&quot;</em>. A failing execution opens on the situation block (<a href="/guide/first-failure.html">Your first failure, explained</a>), then the evidence card and the <strong>More ways to fix</strong> toolbox (<a href="./evidence.html">Failure evidence</a>). The test case page shows the test&#39;s history (<a href="./evidence.html#the-test-case-page">The test case page</a>). Both can be exported as a file with <a href="./offline-export.html">Offline export</a>.</p><h2 id="failure-cluster-detail" tabindex="-1">Failure cluster detail <a class="header-anchor" href="#failure-cluster-detail" aria-label="Permalink to &quot;Failure cluster detail&quot;">​</a></h2><p><code>/failure-clusters/:id</code>: every test that failed for one cause. It opens on the same situation block, with the occurrence sparkline, what changed and the state line, then the affected tests and their evidence (<a href="./failure-clusters.html#the-cluster-page">Failure clusters &amp; the inbox</a>). The <strong>More ways to fix</strong> toolbox holds the <a href="./ai-diagnosis.html">AI diagnosis</a>, the <a href="./locator-healing.html">locator fix</a> and the <a href="./fix-plans.html">fix plan</a>.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p><code>/setup</code>, administrators only: the reporter setup steps and a checklist of which optional capabilities this instance actually uses, judged from the data it holds (<a href="/operate/capabilities.html">Choose what you use</a>).</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><code>/settings</code>: your <strong>Account</strong> and connected accounts (<a href="/operate/authentication.html#oauth-google-github">OAuth</a>), <strong>Users</strong> (<a href="/operate/authentication.html">Authentication</a>, <a href="/operate/api-keys.html">API keys</a>), <strong>Groups</strong> (<a href="/operate/project-access.html#groups">Groups</a>), <strong>Permissions</strong> (<a href="/operate/project-access.html#permission-grid">Permission grid</a>), <strong>Roles</strong> (what each role can do, read-only), <strong>Storage</strong> (<a href="/operate/storage.html#storage-management">Storage</a>), <strong>Tags</strong>, <strong>Pull requests</strong> (<a href="./pr-feedback.html">Pull-request feedback</a>), <strong>Auto-heal</strong> (<a href="./auto-heal.html">Auto-heal PRs</a>), <strong>Integrations</strong> (<a href="/operate/integrations.html">Integrations</a>), <strong>Performance</strong> (wasted-time patterns and timeout hygiene), <strong>AI</strong> (<a href="/guide/ai-provider.html">AI provider</a>), <strong>Notifications</strong> (<a href="./notifications.html">Notifications &amp; alerts</a>) and <strong>Localization</strong> (<a href="/operate/localization.html">Localization</a>). A setting backed by an environment variable is shown read-only with the variable&#39;s name (<a href="/reference/configuration.html">Configuration reference</a>).</p><p>The sidebar also links the <strong>MCP server</strong> setup page, <code>/mcp</code> (<a href="./mcp.html">MCP server</a>), and the <strong>API docs</strong>, <code>/docs</code>, the instance&#39;s own OpenAPI reference.</p><h2 id="live-demo" tabindex="-1">Live demo <a class="header-anchor" href="#live-demo" aria-label="Permalink to &quot;Live demo&quot;">​</a></h2><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> runs entirely in your browser and adds two controls. <strong>Simulate a test run</strong> replays a reporter&#39;s stream, so you can watch a run arrive. <strong>Acting as</strong> switches between seeded identities to show how <a href="/operate/project-access.html">roles</a> change what each one sees and can do, including changes made on the <a href="/operate/project-access.html#permission-grid">permission grid</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/concepts.html">Core concepts</a>: the words this map uses</li><li><a href="/guide/first-failure.html">Your first failure, explained</a>: the page you open most, read top to bottom</li><li><a href="/reference/features.html">All features</a>: every feature and where it lives</li><li><a href="/reference/keyboard-shortcuts.html">Keyboard shortcuts</a>: the command palette and the go-to keys</li></ul>',32)])])}const f=t(o,[["render",n]]);export{p as __pageData,f as default};
